+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * Name and status criteria for narrowing the customer list.
+ *
+ * @param name     free-text search; a customer matches when every
+ *                 whitespace-separated term of {@code name} is a substring of
+ *                 the customer's first name or last name, ignoring case and
+ *                 accents. A blank name matches every customer.
+ * @param statuses statuses to include; an empty set matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Whether the given customer satisfies both the name and status criteria. */
+    public boolean matches(Customer customer) {
+        return matchesName(customer) && matchesStatus(customer);
+    }
+
+    private boolean matchesName(Customer customer) {
+        List<String> terms = terms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private boolean matchesStatus(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private List<String> terms() {
+        String trimmed = name.trim();
+        if (trimmed.isEmpty()) {
+            return List.of();
+        }
+        return Arrays.stream(WHITESPACE.split(trimmed)).map(CustomerFilter::normalize).toList();
+    }
+
+    /** Case- and accent-insensitive normal form used for matching. */
+    private static String normalize(String s) {
+        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
+    }
+}
