+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.assertions.PlaywrightAssertions;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.HasTestView;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * Real-browser checks for behaviour a browserless test cannot see: the
+ * address bar and how many backend queries typing actually costs.
+ */
+@SpringBootTest(classes = Application.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT implements HasTestView {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @BeforeEach
+    void clearLog() {
+        queryLog.clear();
+    }
+
+    private TextFieldElement nameFilter() {
+        return new TextFieldElement(page.locator("vaadin-text-field[placeholder='Filter by name']"));
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private GridElement grid() {
+        return GridElement.get(page);
+    }
+
+    @Test
+    void typingNarrowsTheGridWithoutOneQueryPerKeystroke() {
+        int pageQueriesBefore = queryLog.pageQueries().size();
+
+        Locator input = nameFilter().getInputLocator();
+        input.pressSequentially("aaltonen", new Locator.PressSequentiallyOptions().setDelay(60));
+        page.waitForTimeout(800);
+
+        grid().waitForGridToStopLoading();
+
+        int pageQueriesAfter = queryLog.pageQueries().size() - pageQueriesBefore;
+        assertEquals(15, grid().getTotalRowCount(), "sanity check: the typed name should have matched rows");
+        assertTrue(pageQueriesAfter >= 1 && pageQueriesAfter <= 2,
+                "Typing an eight-letter name should cost one or two backend page queries, cost " + pageQueriesAfter);
+    }
+
+    @Test
+    void typingUpdatesTheAddressBarWithoutReplacingHistoryPerKeystroke() {
+        Locator input = nameFilter().getInputLocator();
+        input.pressSequentially("vir", new Locator.PressSequentiallyOptions().setDelay(60));
+        page.waitForTimeout(800);
+
+        PlaywrightAssertions.assertThat(page).hasURL(java.util.regex.Pattern.compile(".*name=vir.*"));
+
+        input.fill("");
+        input.dispatchEvent("change");
+        page.waitForTimeout(800);
+
+        assertFalse(page.url().contains("name="), "Clearing the filter must remove the name parameter");
+    }
+
+    @Test
+    void selectingAStatusUpdatesTheAddressBar() {
+        statusFilter().selectItem("ACTIVE");
+        page.waitForTimeout(300);
+
+        assertTrue(page.url().contains("status=ACTIVE"), "Selecting a status must add it to the address bar");
+
+        statusFilter().deselectItem("ACTIVE");
+        page.waitForTimeout(300);
+
+        assertFalse(page.url().contains("status="), "Clearing the status filter must remove the parameter");
+    }
+
+    @Test
+    void openingAUrlWithParametersAppliesAndShowsTheFilter() {
+        page.navigate(getUrl() + "/?name=ada+aal&status=ACTIVE,CLOSED");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        assertEquals("ada aal", nameFilter().getValue());
+        assertEquals(java.util.Set.of("ACTIVE", "CLOSED"), java.util.Set.copyOf(statusFilter().getSelectedItems()));
+        grid().assertRowCount(1);
+    }
+}
